323:
SELECT DISTINCT m."label"
FROM "molecule" m
WHERE m."molecule_id" LIKE 'TR000';

239:
SELECT COUNT(DISTINCT c."bond_id") AS connection_count
FROM "connected" c
WHERE c."atom_id" LIKE 'TR%_19' OR c."atom_id2" LIKE 'TR%_19';

355:
SELECT DISTINCT "keywords"
FROM "cards"
WHERE LOWER("name") LIKE LOWER('%Angel of Mercy%');

453:
SELECT DISTINCT "convertedmanacost"
FROM "cards"
WHERE "name" LIKE '%Ancestor''s Chosen%';

588:
SELECT COUNT(*) AS total_comments
FROM "comments"
WHERE CAST("userid" AS BIGINT) = 13;

745:
SELECT DISTINCT "publisher"."id"
FROM "publisher"
WHERE "publisher"."publisher_name" LIKE '%Star Trek%';

803:
SELECT DISTINCT "superpower"."id"
FROM "superpower"
WHERE LOWER("superpower"."power_name") LIKE '%cryokinesis%';

747:
SELECT COUNT(*) AS total_superheroes_without_full_name
FROM "superhero" s
WHERE s."full_name" IS NULL OR TRIM(s."full_name") = '-' OR TRIM(s."full_name") = '';

1377:
SELECT COUNT(DISTINCT "member_id") AS president_count
FROM "member"
WHERE LOWER("position") LIKE '%president%';
